from typing import List

class Solution:
    def minFallingPathSum(self, grid: List[List[int]]) -> int:
        n = len(grid)
        dp = grid[0][:]
        for i in range(1, n):
            # 找出上一行最小值与次小值及其列，保证非同列转移取到最优
            first = second = float('inf')
            idx = -1
            for j, v in enumerate(dp):
                if v < first:
                    second, first, idx = first, v, j
                elif v < second:
                    second = v
            ndp = [0] * n
            for j in range(n):
                best = first if j != idx else second
                ndp[j] = grid[i][j] + best
            dp = ndp
        return min(dp)

class Solution:
    def minFallingPathSum(self, grid: list[list[int]]) -> int:
        n = len(grid)
        if n == 1:
            return grid[0][0]

        # 初始化第一行的最小值、次小值及其列索引
        min1_val, min1_idx = float('inf'), -1
        min2_val, min2_idx = float('inf'), -1

        for j in range(n):
            val = grid[0][j]
            if val < min1_val:
                min2_val, min2_idx = min1_val, min1_idx
                min1_val, min1_idx = val, j
            elif val < min2_val:
                min2_val, min2_idx = val, j

        # 从第二行开始迭代
        for i in range(1, n):
            new_min1_val, new_min1_idx = float('inf'), -1
            new_min2_val, new_min2_idx = float('inf'), -1

            for j in range(n):
                # 如果当前列不是上一行最小值的列，则选上一行最小值；否则选次小值
                prev_best = min1_val if j != min1_idx else min2_val
                current_sum = grid[i][j] + prev_best

                if current_sum < new_min1_val:
                    new_min2_val, new_min2_idx = new_min1_val, new_min1_idx
                    new_min1_val, new_min1_idx = current_sum, j
                elif current_sum < new_min2_val:
                    new_min2_val, new_min2_idx = current_sum, j

            min1_val, min1_idx = new_min1_val, new_min1_idx
            min2_val, min2_idx = new_min2_val, new_min2_idx

        return min1_val

class Solution:
    def addBinary(self, a: str, b: str) -> str:
        i, j = len(a) - 1, len(b) - 1
        carry = 0
        res = []

        # 不变量：res 逆序保存已计算位，carry 表示当前位进位
        while i >= 0 or j >= 0 or carry:
            total = carry
            if i >= 0:
                total += ord(a[i]) - 48
                i -= 1
            if j >= 0:
                total += ord(b[j]) - 48
                j -= 1
            res.append(chr(48 + (total & 1)))
            carry = total >> 1

        return ''.join(reversed(res))

class Solution:
    def addBinary(self, a: str, b: str) -> str:
        res = []
        carry = 0
        i, j = len(a) - 1, len(b) - 1
        while i >= 0 or j >= 0 or carry:
            total = carry
            if i >= 0:
                total += int(a[i])
                i -= 1
            if j >= 0:
                total += int(b[j])
                j -= 1
            res.append(str(total % 2))
            carry = total // 2
        return ''.join(res[::-1])

