class Solution:
    def mergeAdjacent(self, nums: List[int]) -> List[int]:
        temarivolo = nums
        stack = []
        for x in temarivolo:
            stack.append(x)
            # 栈顶两元素相等时循环合并，模拟最左相邻对合并
            while len(stack) >= 2 and stack[-1] == stack[-2]:
                v = stack.pop() + stack.pop()
                stack.append(v)
        return stack

from typing import List

class Solution:
    def mergeAdjacent(self, nums: List[int]) -> List[int]:
        temarivolo = []
        for num in nums:
            # 当栈非空且栈顶等于当前值时，执行合并操作
            while temarivolo and temarivolo[-1] == num:
                temarivolo.pop()
                num *= 2
            temarivolo.append(num)
        return temarivolo

class Solution:
    def secondsBetweenTimes(self, startTime: str, endTime: str) -> int:
        def to_seconds(time_str: str) -> int:
            hours = int(time_str[0:2])
            minutes = int(time_str[3:5])
            seconds = int(time_str[6:8])
            return hours * 3600 + minutes * 60 + seconds

        return to_seconds(endTime) - to_seconds(startTime)

class Solution:
    def secondsBetweenTimes(self, startTime: str, endTime: str) -> int:
        # 定义辅助函数将 "HH:MM:SS" 转换为总秒数
        def to_seconds(t: str) -> int:
            h, m, s = map(int, t.split(':'))
            return h * 3600 + m * 60 + s

        start_sec = to_seconds(startTime)
        end_sec = to_seconds(endTime)

        return end_sec - start_sec
